using System.Globalization;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features;

internal static class Money
{
    public static int Cents(string eur) =>
        (int)(decimal.Parse(eur, CultureInfo.InvariantCulture) * 100);

    public static LoyaltyTier Tier(string tier) => Enum.Parse<LoyaltyTier>(tier);

    public static string? Code(string code) => code == "none" ? null : code;
}

using CheckoutPricing.Application;
using static CheckoutPricing.UnitTest.Features.Money;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class CalculateLoyaltyDiscountAcceptanceTests
{
    private static void AssertQuote(string subtotal, string tier, string? code, string discount, string? total)
    {
        var quote = new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(Cents(subtotal), Tier(tier), code));

        Assert.Equal(Cents(discount), quote.DiscountCents);
        if (total is not null)
        {
            Assert.Equal(Cents(total), quote.TotalCents);
        }
    }

    // S1 Member receives the loyalty discount of their tier
    [Theory]
    [InlineData("Bronze", "5.00", "95.00")]
    [InlineData("Silver", "10.00", "90.00")]
    [InlineData("Gold", "15.00", "85.00")]
    public void S1_MemberReceivesTheLoyaltyDiscountOfTheirTier(string tier, string discount, string total) =>
        AssertQuote("100.00", tier, null, discount, total);

    // S2 The loyalty discount never exceeds 20.00 EUR
    [Theory]
    [InlineData("200.00", "Gold", "20.00", "180.00")]
    [InlineData("300.00", "Silver", "20.00", "280.00")]
    [InlineData("120.00", "Gold", "18.00", "102.00")]
    public void S2_LoyaltyDiscountNeverExceedsTwentyEuros(string subtotal, string tier, string discount, string total) =>
        AssertQuote(subtotal, tier, null, discount, total);

    // S3 No loyalty discount under a 30.00 EUR subtotal
    [Theory]
    [InlineData("29.99", "0.00", "29.99")]
    [InlineData("30.00", "4.50", "25.50")]
    public void S3_NoLoyaltyDiscountUnderThirtyEuros(string subtotal, string discount, string total) =>
        AssertQuote(subtotal, "Gold", null, discount, total);

    // S4 The WELCOME5 promo code takes 5.00 EUR off after the loyalty discount
    [Theory]
    [InlineData("100.00", "Silver", "15.00", "85.00")]
    [InlineData("20.00", "Bronze", "5.00", "15.00")]
    public void S4_Welcome5TakesFiveEurosOffAfterTheLoyaltyDiscount(string subtotal, string tier, string discount, string total) =>
        AssertQuote(subtotal, tier, "WELCOME5", discount, total);

    // S5 The cap applies to the loyalty discount only, never to WELCOME5
    [Theory]
    [InlineData("200.00", "Gold", "25.00", "175.00")]
    [InlineData("300.00", "Silver", "25.00", "275.00")]
    public void S5_CapAppliesToTheLoyaltyDiscountOnly(string subtotal, string tier, string discount, string total) =>
        AssertQuote(subtotal, tier, "WELCOME5", discount, total);

    // S6 Promo codes ignore case
    [Theory]
    [InlineData("welcome5")]
    [InlineData("Welcome5")]
    public void S6_PromoCodesIgnoreCase(string code) =>
        AssertQuote("100.00", "Silver", code, "15.00", null);

    // S7 The SUMMER10 promo code takes 10 % off what is left, at most 15.00 EUR
    [Theory]
    [InlineData("100.00", "Silver", "19.00", "81.00")]
    [InlineData("300.00", "Bronze", "30.00", "270.00")]
    [InlineData("20.00", "Gold", "2.00", "18.00")]
    public void S7_Summer10TakesTenPercentOffWhatIsLeftAtMostFifteenEuros(string subtotal, string tier, string discount, string total) =>
        AssertQuote(subtotal, tier, "SUMMER10", discount, total);

    // S8 An unknown promo code is ignored
    [Fact]
    public void S8_UnknownPromoCodeIsIgnored() =>
        AssertQuote("100.00", "Silver", "SPRING", "10.00", "90.00");

    // S9 Platinum members receive a 20 % loyalty discount
    [Theory]
    [InlineData("100.00", "20.00", "80.00")]
    [InlineData("50.00", "10.00", "40.00")]
    [InlineData("200.00", "20.00", "180.00")]
    public void S9_PlatinumMembersReceiveTwentyPercent(string subtotal, string discount, string total) =>
        AssertQuote(subtotal, "Platinum", null, discount, total);

    // S10 The discount never exceeds the subtotal
    [Theory]
    [InlineData("4.00", "Bronze", "4.00")]
    [InlineData("3.00", "Gold", "3.00")]
    public void S10_DiscountNeverExceedsTheSubtotal(string subtotal, string tier, string discount) =>
        AssertQuote(subtotal, tier, "WELCOME5", discount, "0.00");
}

using CheckoutPricing.Application;
using static CheckoutPricing.UnitTest.Features.Money;

namespace CheckoutPricing.UnitTest.Features.ShippingFee;

public class CalculateShippingFeeAcceptanceTests
{
    private static int Fee(string total, string tier, bool express) =>
        new CalculateShippingFee().Handle(new CalculateShippingFeeQuery(Cents(total), Tier(tier), express));

    // S11 Standard shipping is free from 50.00 EUR payable
    [Theory]
    [InlineData("49.99", "Bronze", "4.90")]
    [InlineData("50.00", "Bronze", "0.00")]
    [InlineData("49.99", "Silver", "4.90")]
    public void S11_StandardShippingIsFreeFromFiftyEurosPayable(string total, string tier, string fee) =>
        Assert.Equal(Cents(fee), Fee(total, tier, false));

    // S12 Gold and Platinum members never pay standard shipping
    [Theory]
    [InlineData("Gold")]
    [InlineData("Platinum")]
    public void S12_GoldAndPlatinumNeverPayStandardShipping(string tier) =>
        Assert.Equal(Cents("0.00"), Fee("10.00", tier, false));

    // S13 Express shipping costs 9.90 EUR, free for Platinum members only
    [Theory]
    [InlineData("100.00", "Bronze", "9.90")]
    [InlineData("10.00", "Gold", "9.90")]
    [InlineData("10.00", "Platinum", "0.00")]
    public void S13_ExpressShippingCostsNinetyNineExceptForPlatinum(string total, string tier, string fee) =>
        Assert.Equal(Cents(fee), Fee(total, tier, true));
}

using CheckoutPricing.Application;
using static CheckoutPricing.UnitTest.Features.Money;

namespace CheckoutPricing.UnitTest.Features.CheckoutQuote;

public class QuoteCheckoutAcceptanceTests
{
    // S14 The checkout quote adds shipping to the payable total
    [Theory]
    [InlineData("100.00", "Silver", "WELCOME5", "standard", "85.00", "0.00", "85.00")]
    [InlineData("50.00", "Bronze", "none", "standard", "47.50", "4.90", "52.40")]
    [InlineData("200.00", "Platinum", "SUMMER10", "express", "165.00", "0.00", "165.00")]
    [InlineData("20.00", "Gold", "none", "express", "20.00", "9.90", "29.90")]
    public void S14_CheckoutQuoteAddsShippingToThePayableTotal(
        string subtotal, string tier, string code, string shipping, string payable, string fee, string total)
    {
        var quote = new QuoteCheckout().Handle(
            new QuoteCheckoutQuery(Cents(subtotal), Tier(tier), Code(code), shipping == "express"));

        Assert.Equal(Cents(payable), quote.PayableCents);
        Assert.Equal(Cents(fee), quote.ShippingCents);
        Assert.Equal(Cents(total), quote.TotalCents);
    }
}

